options.types:
type Status = 'draft' | 'submitted' | 'paid';
const next: { [S in Status]: Status[] } = { draft: ['submitted'], submitted: ['paid'], paid: [] };
function advance<F extends Status>(from: F, to: (typeof next)[F][number]): Status { return to; }

interface Draft { kind: 'draft' }
interface Submitted { kind: 'submitted' }
interface Paid { kind: 'paid' }
function submit(o: Draft): Submitted { return { kind: 'submitted' }; }
function pay(o: Submitted): Paid { return { kind: 'paid' }; }
